def solve():
    n = 4
    # Generate all 4x4 Latin Squares? No, that's too many.
    # Let's use backtracking to find one.
    grid = [[-1]*n for _ in range(n)]

    def backtrack(r, c):
        if r == n:
            return True
        next_r, next_c = (r, c + 1) if c < n - 1 else (r + 1, 0)

        for val in range(4):
            # Check row
            if val in grid[r]: continue
            # Check col
            if val in [grid[i][c] for i in range(r)]: continue

            grid[r][c] = val
            # Check 2x2
            if r > 0 and c > 0:
                cells = [(r-1, c-1), (r, c-1), (r-1, c), (r, c)]
                if len(set(grid[i][j] for i, j in cells)) != 4:
                    grid[r][c] = -1
                    continue

            if backtrack(next_r, next_c):
                return True
            grid[r][c] = -1
        return False

    if backtrack(0, 0):
        print("Found Latin Square with 2x2 property:")
