def solve_K3_C4():
    grid = [[-1 for _ in range(5)] for _ in range(5)]

    def get_connected_sets(r, c, size):
        res = []
        def backtrack(current_set, neighbors):
            if len(current_set) == size:
                res.append(list(current_set))
                return
            for nr, nc in list(neighbors):
                new_set = current_set + [(nr, nc)]
                new_neighbors = set(neighbors)
                new_neighbors.remove((nr, nc))
                for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                    nnr, nnc = nr+dr, nc+dc
                    if 0 <= nnr < 5 and 0 <= nnc < 5 and grid[nnr][nnc] != -1 and (nnr, nnc) not in new_set:
                        new_neighbors.add((nnr, nnc))
                backtrack(new_set, new_neighbors)

        start_neighbors = set()
        for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < 5 and 0 <= nc < 5 and grid[nr][nc] != -1:
                start_neighbors.add((nr, nc))
        backtrack([(r,c)], start_neighbors)
        return res

    def is_valid(r, c):
        sets = get_connected_sets(r, c, 4)
        for s in sets:
            colors = set()
            for sr, sc in s:
                colors.add(grid[sr][sc])
            if len(colors) < 3:
                return False
        return True

    def backtrack_grid(r, c):
        if r == 5:
            return True
        next_r, next_c = (r, c+1) if c < 4 else (r+1, 0)
        for color in range(3):
            grid[r][c] = color
            if is_valid(r, c):
                if backtrack_grid(next_r, next_c):
                    return True
            grid[r][c] = -1
        return False

    if backtrack_grid(0, 0):
        return "Found 3-coloring for C=4"
    else:
        return "No 3-coloring for C=4"

