def solve_k_small_fixed(k=3):
    perms = list(itertools.permutations(range(k)))
    for p1 in perms:
        for p2 in perms:
            for p3 in perms:
                grid = [list(p1), list(p2), list(p3)]
                # Check columns
                valid_cols = True
                for j in range(3):
                    if len(set(grid[i][j] for i in range(3))) != 3:
                        valid_cols = False
                        break
                if not valid_cols:
                    continue

                # Tiled grid (6x6 is enough to find any component of area 4)
                tiled = [[grid[i%3][j%3] for j in range(6)] for i in range(6)]

                is_valid_coloring = True
                # For every pair of colors {i, j}
                for i in range(k):
                    for j in range(i + 1, k):
                        visited = set()
                        for r in range(6):
                            for c in range(6):
                                if (r, c) not in visited and tiled[r][c] in (i, j):
                                    # Start BFS
                                    q = [(r, c)]
                                    visited.add((r, c))
                                    component_size = 0
                                    while q:
                                        curr_r, curr_c = q.pop(0)
                                        component_size += 1
                                        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                                            nr, nc = curr_r + dr, curr_c + dc
                                            if 0 <= nr < 6 and 0 <= nc < 6 and \
                                               (nr, nc) not in visited and tiled[nr][nc] in (i, j):
                                                visited.add((nr, nc))
                                                q.append((nr, nc))
                                    if component_size >= 4:
                                        is_valid_coloring = False
                                        break
                            if not is_valid_coloring:
                                break
                    if not is_valid_coloring:
                        break

                if is_valid_coloring:
                    return grid
    return None

